use filmcraft_project::{Param,ParamValue};use filmcraft_render::{effects::{apply,FxCtx},image::Image};use serde_json::json;
fn main(){let mut cases=vec![];for(w,h)in[(1,7),(7,1),(6,4),(18,10)]{for mode in [0u32,1]{for amount in [0.,0.0005,1.25,10.,1000.]{for blend in [0.,37.5,100.]{for angle in[-90.,-37.25,0.,90.]{for center in[None,Some([Some(1.123456789012),None]),Some([None,Some(-0.75)]),Some([Some(-3.25),Some(4.125)])]{for scale in[0.5f32,1.]{
let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]][(i+i/w)%5]).collect();let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;[filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[1]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[2]as f32/255.)*a,a]}).collect();let mut out=Image{w,h,px};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="rgb_split").unwrap().instance();for(id,value)in [("mode",ParamValue::Choice(mode)),("amount",ParamValue::Float(amount)),("blend",ParamValue::Float(blend))]{e.params.insert(id.into(),Param::new(value));}e.params.insert("angle".into(),Param::new(ParamValue::Float(angle)));if let Some(c)=center{e.params.insert("center".into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(c[0].unwrap_or(f64::NAN),c[1].unwrap_or(f64::NAN)))));}
let cx=FxCtx{t:filmcraft_time::Tick::ZERO,px_scale:scale,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut out,&e,&cx);cases.push(json!({"parameters":{"mode":mode,"amount":amount,"blend":blend,"angle":angle,"center":center},"width":w,"height":h,"rgba":rgba,"scale":scale,"bits":out.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
}}}}}}}let mut media=vec![];
for mode in [0u32,1] {for tick in [0u64,250000,500000] {
let rgba:Vec<u8>=(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12{255}else{32};[v,v,v,128]}).collect();let mut frames=vec![];
for index in 0..(1000000-tick).div_ceil(100000){let local=(tick+index*100000).min(500000);let t=local as f64/500000.;let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;let v=filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a;[v,v,v,a]}).collect();let mut frame=Image{w:16,h:16,px};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="rgb_split").unwrap().instance();
for(id,value)in [("mode",ParamValue::Choice(mode)),("amount",ParamValue::Float(1.25+8.75*t)),("angle",ParamValue::Float(-37.25+127.25*t)),("blend",ParamValue::Float(75.*t)),("center",ParamValue::Vec2(filmcraft_geom::Vec2::new(8.+(2.123456789012-8.)*t,8.-6.25*t)))]{e.params.insert(id.into(),Param::new(value));}
let cx=FxCtx{t:filmcraft_time::Tick(local as i64),px_scale:1.,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut frame,&e,&cx);frames.push(frame.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());}
media.push(json!({"localTick":tick,"parameters":{"mode":mode},"rgba":rgba,"bits":frames[0],"frames":frames}));
}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media}));}
